-- MAIS AÇAÍ SJP — ATUALIZAÇÃO CALDA DE MORANGO (2kg = R$ 73,00 / 70g) + MOUSSE/DANONINHO (100g) + 49 FICHAS
UPDATE public.financeiro_maisacai f
SET dados = jsonb_set(
      jsonb_set(
        f.dados,
        '{insumos}',
        (
          SELECT jsonb_agg(
            CASE
              WHEN i->>'nome' = 'Calda de morango'
              THEN i || '{"qtdEmbalagem": 2000, "precoEmbalagem": 73.0, "atualizadoEm": "2026-11-03"}'::jsonb
              ELSE i
            END
          )
          FROM jsonb_array_elements(f.dados->'insumos') i
        )
      ),
